    todo('<b>đậm</b> & "ngoặc" \'đơn\''), todo('a'), todo('x'.repeat(500)), todo('tab\tvà\nxuống dòng'),
  ];
  assert.deepEqual(parseBackup(toBackupText(todos)), { ok: true, todos });
  assert.deepEqual(parseBackup(toBackupText(list(2000))).ok, true);
});

